INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(118249, 'ruRU', '', 'Потренируйся использовать Героический прыжок.', 24330),
(118250, 'ruRU', '', 'Героический прыжок позволяет перемещаться по полю боя, чтобы достичь любой из этих целей.', 24330),
(118251, 'ruRU', '', 'В пылу битвы бывают моменты, когда тебе нужно быстро переместиться, чтобы избежать опасности... или встретиться с ней лицом к лицу!', 24330),
(118252, 'ruRU', '', 'Используй Смерч, чтобы расправиться с этой группой врагов.', 24330),
(118253, 'ruRU', '', 'Смерч позволяет размахивать оружием широкими дугами, прорубая кровавую полосу среди всех врагов вокруг тебя.', 24330),
(118254, 'ruRU', '', 'Твои противники могут попытаться одолеть тебя числом, но они недооценивают твою истинную силу!', 24330),
(118255, 'ruRU', '', 'Используй Смерч!', 24330),
(118256, 'ruRU', '', 'Смерч может наносить урон нескольким врагам!', 24330),
(118257, 'ruRU', '', 'Используй Рывок к победе!', 24330),
(118258, 'ruRU', '', 'Рывок к победе доступен! Используй его сейчас!', 24330),
(118259, 'ruRU', '', 'Используй Удар!', 24330),
(118260, 'ruRU', '', 'Используй Смертельный удар!', 24330),
(118261, 'ruRU', '', 'Смертельный удар доступен! Используй его сейчас!', 24330),
(118262, 'ruRU', '', 'Используй Удар колосса!', 24330),
(118263, 'ruRU', '', 'Удар колосса доступен! Используй его сейчас!', 24330),
(118264, 'ruRU', '', 'Используй Раскол!', 24330),
(118265, 'ruRU', '', 'Воины не подходят к врагу неторопливой походкой! Используй Рывок, чтобы сократить расстояние до противника. Попробуй!', 24330),
(118266, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как воин оружия.', 24330),
(118267, 'ruRU', '', 'Покажи мне, что ты сражаешься без страха и с яростью!', 24330),
(118268, 'ruRU', '', 'Используй Раскол и Смерч, чтобы расправиться с этой группой врагов.', 24330),
(118269, 'ruRU', '', 'Раскол позволяет атаковать нескольких врагов перед тобой. За каждого поражённого врага твой следующий Смерч наносит дополнительный урон!', 24330),
(118270, 'ruRU', '', 'Смерч — не единственная атака, которую ты можешь использовать против нескольких врагов.', 24330),
(118271, 'ruRU', '', 'Уничтожь врага, чтобы получить возможность использовать Рывок к победе на следующем противнике.', 24330),
(118272, 'ruRU', '', 'Твою способность Рывок к победе можно использовать только в это время, восстанавливая здоровье, пока ты атакуешь нового врага.', 24330),
(118273, 'ruRU', '', 'После того как ты одолеешь противника, твоё сердце запоёт от славы победы!', 24330),
(118274, 'ruRU', '', 'Используй Удар колосса на тренировочном манекене.', 24330),
(118275, 'ruRU', '', 'Одна из твоих самых разрушительных атак — Удар колосса. Всегда используй его, как только он становится доступен, и никакой враг не выстоит против тебя долго.', 24330),
(118276, 'ruRU', '', 'Используй Удар на тренировочном манекене.', 24330),
(118277, 'ruRU', '', 'Нанесение урона врагу накапливает Ярость, что питает твои атаки. Используй Удар, чтобы потратить Ярость и нанести урон врагу.', 24330),
(118278, 'ruRU', '', 'Используй Смертельный удар на тренировочном манекене.', 24330),
(118279, 'ruRU', '', 'Смертельный удар — именно такая атака. Используй его, когда он доступен.', 24330),
(118280, 'ruRU', '', 'Как только ты достигнешь цели, ты будешь автоматически наносить базовые удары, но умелый боец применяет множество продвинутых способностей, чтобы одолеть врага.', 24330),
(118281, 'ruRU', '', 'Используй способность Рывок, чтобы покрыть расстояние до этого тренировочного манекена.', 24330),
(118282, 'ruRU', '', 'Но ты не можешь одолеть противника, что вне досягаемости. К счастью, у тебя есть способность, решающая эту проблему.', 24330),
(118283, 'ruRU', '', 'Воины оружия — непревзойдённые физические бойцы, использующие боевое мастерство и оружие, чтобы сокрушить тех, кто встанет на их пути.', 24330),
(118384, 'ruRU', '', 'Более стойких врагов может потребоваться одолевать с помощью разнообразного набора способностей.', 24330),
(118385, 'ruRU', '', 'Используй Ярость тигра, чтобы восстановить немного энергии, а затем атакуй тренировочный манекен Терзанием.', 24330),
(118386, 'ruRU', '', 'Ярость тигра восстанавливает немного энергии, а также увеличивает твой урон на короткое время.', 24330),
(118387, 'ruRU', '', 'Большинству твоих атак требуется энергия. Иногда у тебя может оставаться мало энергии, что лишает тебя возможности использовать какие-либо способности.', 24330),
(118388, 'ruRU', '', 'Используй Истязание на тренировочном манекене.', 24330);
